def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i
    return 1

import math
def _evaluate(coeffs, x):
    """Horner scheme - same value as poly(), but overflow friendly."""
    acc = 0.0
    for c in reversed(coeffs):
        acc = acc * x + c
    return acc
def _derivative(coeffs):
    """Coefficient list of p'(x)."""
    return [i * c for i, c in enumerate(coeffs)][1:]
def _scale(coeffs, x):
    """Natural size of |p(x)| at x:  sum |a_i| * |x|^i  (backward-error scale)."""
    total = 0.0
    power = 1.0
    ax = abs(x)
    for c in coeffs:
        term = abs(c) * power
        if not math.isfinite(term):
            return math.inf
        total += term
        power *= ax
        if not math.isfinite(power):
            return math.inf
    return total
def _is_root(coeffs, x, tol=1e-6):
    """True if x is a (numerically) valid zero of the polynomial."""
    if not math.isfinite(x):
        return False
    fx = _evaluate(coeffs, x)
    if fx == 0.0:
        return True
    if not math.isfinite(fx):
        return False
    s = _scale(coeffs, x)
    return math.isfinite(s) and s > 0.0 and abs(fx) <= tol * s
def _bisect(f, lo, hi, flo, fhi, iters=400):
    """Bisection on a bracketing interval [lo, hi]."""
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        if mid == lo or mid == hi:          # interval exhausted
            break
        fmid = f(mid)
        if fmid == 0.0:
            return mid
        if (flo < 0.0) != (fmid < 0.0):
            hi, fhi = mid, fmid
        else:
            lo, flo = mid, fmid
    return 0.5 * (lo + hi)
def _newton(f, df, x0, iters=100):
    """Newton's method with safeguards."""
    x = x0
    for _ in range(iters):
        fx = f(x)
        if fx == 0.0:
            return x
        dfx = df(x)
        if dfx == 0.0 or not math.isfinite(dfx):
            break
        step = fx / dfx
        if not math.isfinite(step):
            break
        xn = x - step
        if not math.isfinite(xn) or xn == x:
            break
        x = xn
    return x
def _sample_points(bound, n_linear=4000):
    """Dense linear grid on [-bound, bound] + logarithmic grid near 0."""
    pts = set()
    for i in range(n_linear + 1):
        pts.add(-bound + 2.0 * bound * i / n_linear)
    k = -20                                   # roots may be tiny or huge
    while 10.0 ** k <= bound:
        decade = 10.0 ** k
        for m in (1.0, 2.0, 5.0):
            for s in (-1.0, 1.0):
                v = s * m * decade
                if -bound <= v <= bound:
                    pts.add(v)
        k += 1
    return sorted(pts)
def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    if not xs:
        raise ValueError("coefficient list must not be empty")

    coeffs = [float(c) for c in xs]

    # drop leading (highest-degree) zero coefficients
    while len(coeffs) > 1 and coeffs[-1] == 0.0:
        coeffs.pop()

    if len(coeffs) == 1:
        raise ValueError("constant polynomial has no zero")

    # ---- trivial cases -------------------------------------------------
    if coeffs[0] == 0.0:
        return 0.0
    if len(coeffs) == 2:                       # a + b*x = 0
        return -coeffs[0] / coeffs[1]

    f = lambda t: _evaluate(coeffs, t)

    # ---- 1) fast & accurate path: companion-matrix eigenvalues --------
    try:
        import numpy as np
        raw_roots = np.roots(list(reversed(coeffs)))   # highest degree first
        good = []
        for z in raw_roots:
            z = complex(z)
            if abs(z.imag) <= 1e-6 * max(1.0, abs(z)):
                xr = float(z.real)
                if _is_root(coeffs, xr):
                    good.append(xr)
        if good:
            return min(good, key=abs)
    except Exception:
        pass                                          # fall through

    # ---- 2) pure-Python fallback: bracket + bisection ------------------
    lead = coeffs[-1]
    bound = 1.0 + max(abs(c) for c in coeffs[:-1]) / abs(lead)   # Cauchy bound
    bound = min(max(bound, 1.0), 1e12)

    candidates = []
    prev_x = prev_f = None
    for x in _sample_points(bound):
        fx = f(x)
        if fx == 0.0:
            candidates.append(x)
        if (prev_x is not None and prev_f is not None
                and math.isfinite(prev_f) and math.isfinite(fx)):
            if (prev_f < 0.0) != (fx < 0.0):            # sign change -> root
                candidates.append(_bisect(f, prev_x, x, prev_f, fx))
        prev_x, prev_f = x, fx

    good = [c for c in candidates if _is_root(coeffs, c)]
    if good:
        return min(good, key=abs)

    # ---- 3) last resort: Newton from many seeds -----------------------
    d = _derivative(coeffs)
    g = lambda t: _evaluate(d, t)
    best = None
    seeds = _sample_points(bound, n_linear=200)[::2] + [0.0]
    for seed in seeds:
        r = _newton(f, g, seed)
        if _is_root(coeffs, r) and (best is None or abs(r) < abs(best)):
            best = r
    if best is not None:
        return best

    raise RuntimeError("could not locate a real zero of the polynomial")

def is_simple_power(x, n):
    """Return True if x == n**k for some integer k >= 0, else False."""
    # k == 0 -> n**0 == 1, valid for every base.
    if x == 1:
        return True

    # --- degenerate bases -------------------------------------------------
    if n == 0:
        # 0**k == 0 for k >= 1 (the k == 0 case was covered above).
        return x == 0
    if n == 1:
        # 1**k == 1 always, and we already know x != 1.
        return False
    if n == -1:
        # (-1)**k is either 1 or -1; x != 1 here.
        return x == -1

    # --- general case: walk the powers of n -------------------------------
    p = 1
    while abs(p) < abs(x):
        p *= n
        if p == x:
            return True
    return p == x

def sort_array(array):
    """
    Given an array of non-negative integers, return a copy of the given array after sorting,
    you will sort the given array in ascending order if the sum( first index value, last index value) is odd,
    or sort it in descending order if the sum( first index value, last index value) is even.

    Note:
    * don't change the given array.

    Examples:
    * sort_array([]) => []
    * sort_array([5]) => [5]
    * sort_array([2, 4, 3, 0, 1, 5]) => [0, 1, 2, 3, 4, 5]
    * sort_array([2, 4, 3, 0, 1, 5, 6]) => [6, 5, 4, 3, 2, 1, 0]
    """
    if len(array) <= 1:
        return array[:]

    total = array[0] + array[-1]

    if total % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n < 2:
        return []

    primes = []
    for num in range(2, n):
        is_prime = True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

def valid_date(date):
    """You have to write a function which validates a given date string and
    returns True if the date is valid otherwise False.
    The date is valid if all of the following rules are satisfied:
    1. The date string is not empty.
    2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
    3. The months should not be less than 1 or higher than 12.
    4. The date should be in the format: mm-dd-yyyy

    for example:
    valid_date('03-11-2000') => True

    valid_date('15-01-2012') => False

    valid_date('04-0-2040') => False

    valid_date('06-04-2020') => True

    valid_date('06/04/2020') => False
    """
    # Rule 1: The date string is not empty
    if not date:
        return False

    # Rule 4: The date should be in the format mm-dd-yyyy (split on hyphens)
    parts = date.split('-')
    if len(parts) != 3:
        return False

    # Each part must consist solely of digits
    for part in parts:
        if not part.isdigit():
            return False

    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])

    # Rule 3: Month must be between 1 and 12
    if month < 1 or month > 12:
        return False

    # Rule 2: Validate day based on month
    if month in (1, 3, 5, 7, 8, 10, 12):
        if day < 1 or day > 31:
            return False
    elif month in (4, 6, 9, 11):
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True
